@Override
@Parameter(excluded = true, attribute = false)
public List<String> getPrefixes() {
    // parent prefix + method name
    if (parentPrefix != null) {
        List<String> prefixes = new ArrayList<>();
        prefixes.add(parentPrefix + "." + this.getName());
        return prefixes;
    }
    return null;
}

