     * @return non-null read-only {@link List}
     * @since 2.7.6
     */
    static List<Method> getMethods(
            Class<?> declaringClass,
            boolean includeInheritedTypes,
            boolean publicOnly,
            Predicate<Method>... methodsToFilter) {

